        val Identity = DMat4()
        val Zero = DMat4(0.0)
    }
}
/** Row vector times matrix: the same as transpose(m) * v. */
operator fun DVec4.times(m: DMat4) = DVec4(dot(this, m[0]), dot(this, m[1]), dot(this, m[2]), dot(this, m[3]))
operator fun Double.times(m: DMat4) = m * this

typealias Mat2x2 = Mat2
typealias Mat3x3 = Mat3
typealias Mat4x4 = Mat4
typealias DMat2x2 = DMat2
typealias DMat3x3 = DMat3
typealias DMat4x4 = DMat4
